#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
static void putd(uint8_t*out,int off,double x){uint64_t b;memcpy(&b,&x,8);for(int k=0;k<8;k++)out[off+k]=(uint8_t)(b>>(8*k));}
static int token(const int64_t*v,int len,uint64_t*out){uint64_t key=0;for(int i=0;i<len;i++){int x=(int)v[i];if(x>=65&&x<=90)x+=32;if(!((x>=97&&x<=122)||(x>=48&&x<=57)||x==39))return 0;key=key*128+(uint64_t)x;}*out=key;return 1;}
int64_t naive_bayes_text_classification(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<7)return -1;int d=(int)v[0];int64_t alpha=v[1];if(d<2||d>6||alpha<1||alpha>10000)return -1;uint64_t words[6]={0},q=0;int labels[6]={0},pos=2,seen[2]={0},total[2]={0};for(int i=0;i<d;i++){if((size_t)(pos+2)>n)return -1;int64_t lab=v[pos++],len=v[pos++];if((lab!=0&&lab!=1)||len<0||len>8||(size_t)(pos+len)>n||!token(v+pos,(int)len,&words[i]))return -1;labels[i]=(int)lab;seen[lab]=1;total[lab]+=len>0;pos+=(int)len;}if((size_t)pos>=n)return -1;int64_t ql=v[pos++];if(ql<0||ql>8||(size_t)(pos+ql)!=n||!token(v+pos,(int)ql,&q)||!seen[0]||!seen[1])return -1;int vocab=0;for(int i=0;i<d;i++)if(words[i]){int fresh=1;for(int j=0;j<i;j++)if(words[j]==words[i])fresh=0;if(fresh)vocab++;}if(!vocab&&ql)return -1;if(!out||cap<16)return -2;double score[2];for(int c=0;c<2;c++){int docs=0,count=0;for(int i=0;i<d;i++)if(labels[i]==c){docs++;if(ql&&words[i]==q)count++;}score[c]=log((double)docs/d);if(ql){double a=(double)alpha/1000.0;score[c]+=log((count+a)/(total[c]+a*vocab));}}double hi=score[0]>score[1]?score[0]:score[1],a=exp(score[0]-hi),b=exp(score[1]-hi);putd(out,0,a/(a+b));putd(out,8,b/(a+b));return 16;}
